def build_page(kind, title, subtitle, tabs, body, css="", js="", nav=""):
    """tabs : liste (id, libellé). body : HTML des vues (<section class="view" id="v-ID">)."""
    fonts = "".join("@font-face{font-family:'Open Sans';font-style:normal;font-weight:%s;"
                    "src:url(data:font/woff2;base64,%s) format('woff2')}" % (w, b) for w, b in FONTS_B64.items())
    tabs_html = "".join(f'<button class="tab{" on" if i == 0 else ""}" data-v="{t}" onclick="tab(\'{t}\')">{lab}</button>'
                        for i, (t, lab) in enumerate(tabs))
    first = tabs[0][0] if tabs else ""
    return ("<!doctype html><html lang='fr'><head><meta charset='utf-8'><style>" + fonts +
            BASE_CSS.replace("%%BINBG%%", BIN_BG) + css + "</style></head><body><div class='app'>"
            f"<header class='top'>{logo_svg(kind)}<div class='brand'>{title}<small>{subtitle}</small></div>"
            f"<div class='tabs'>{tabs_html}</div><div class='nav'>{nav}</div></header>"
            f"<main class='scroll' id='scroll'>{body}</main></div><div class='toast' id='toast'></div>"
            "<script>" + BASE_JS + js + f"\ntab('{first}');</script></body></html>")


# --------------------------------------------------------------------------- #
# Fenêtre
# --------------------------------------------------------------------------- #
def webview2_available():
    if not IS_WIN:
        return True
    try:
        import winreg  # type: ignore
        sub = r"Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}"
        for root, k in ((winreg.HKEY_LOCAL_MACHINE, "SOFTWARE\\WOW6432Node\\" + sub),
                        (winreg.HKEY_LOCAL_MACHINE, "SOFTWARE\\" + sub), (winreg.HKEY_CURRENT_USER, "SOFTWARE\\" + sub)):
            try:
                with winreg.OpenKey(root, k) as h:
                    v = winreg.QueryValueEx(h, "pv")[0]
                    if v and v != "0.0.0.0":
                        return True
            except OSError:
                pass
    except Exception:
        pass
    return False


def _message(title, text):
    try:
        import tkinter as tk
        from tkinter import messagebox
        r = tk.Tk()
        r.withdraw()
        messagebox.showerror(title, text)
        r.destroy()
    except Exception:
        print(f"{title}: {text}")


def run_window(title, html, bridge, width=1320, height=860, min_size=(1000, 660)):
    if IS_WIN and not webview2_available():
        _message(title, "Ce logiciel nécessite le composant Microsoft Edge WebView2, absent de ce poste.\n\n"
                        "Il s'installe gratuitement depuis le site de Microsoft (« WebView2 Runtime »).")
        return 1
    try:
        import webview
    except Exception as e:
        _message(title, f"Composant d'affichage indisponible : {e}")
        return 1
    win = webview.create_window(title, html=html, js_api=bridge, width=width, height=height,
                                min_size=min_size, background_color="#0b141d")
    bridge._window = win
    webview.start(gui="edgechromium" if IS_WIN else None, debug=False)
    return 0


class BridgeBase:
    """Méthodes communes. Les attributs privés (_x) ne sont pas exposés au JS."""

    def __init__(self):
        self._window = None

    def _js(self, fn, data=None):
        try:
            self._window.evaluate_js(f"window.E && E.{fn} && E.{fn}({json.dumps(data, ensure_ascii=False)})")
        except Exception:
            pass

    def _eval(self, code):
        try:
            return self._window.evaluate_js(code)
        except Exception as e:
            return f"ERR {e}"

    def open_url(self, url):
        if re.match(r"^(https?|ftp)://", url or ""):
            import webbrowser
            webbrowser.open(url)
            return True
        return False

    def save_text(self, filename, content, desc="Fichier"):
        import webview
        mode = getattr(getattr(webview, "FileDialog", None), "SAVE", None)
        if mode is None:
            mode = webview.SAVE_DIALOG
        ext = os.path.splitext(filename)[1]
        desk = os.path.join(os.path.expanduser("~"), "Desktop")
        res = self._window.create_file_dialog(mode, directory=desk if os.path.isdir(desk) else "",
                                              save_filename=filename, file_types=(f"{desc} (*{ext})",))
        if not res:
            return ""
        path = res if isinstance(res, str) else res[0]
        if ext and not path.lower().endswith(ext.lower()):
            path += ext
        with open(path, "w", encoding="utf-8-sig" if ext.lower() == ".csv" else "utf-8", newline="") as fh:
            fh.write(content)
        return path

    def pick_folder(self, start=""):
        import webview
        mode = getattr(getattr(webview, "FileDialog", None), "FOLDER", None)
        if mode is None:
            mode = webview.FOLDER_DIALOG
        res = self._window.create_file_dialog(mode, directory=start or "")
        if not res:
            return ""
        return res if isinstance(res, str) else res[0]


# --------------------------------------------------------------------------- #
# Commandes avec sortie en direct
# --------------------------------------------------------------------------- #
def decode_out(b):
    try:
        return b.decode("utf-8")
    except UnicodeDecodeError:
        for enc in ("oem", "cp850"):
            try:
                return b.decode(enc, "replace")
            except LookupError:
                continue
        return b.decode("latin-1", "replace")


def run(cmd, timeout=20, encoding=None):
    try:
        p = subprocess.run(cmd, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                           timeout=timeout, creationflags=NO_WINDOW)
        raw = p.stdout or b""
        if encoding:
            return raw.decode(encoding, "replace")
        if raw[1:2] == b"\x00":
            return raw.decode("utf-16-le", "replace")
        return decode_out(raw)
    except Exception:
        return ""


PS_PRE = ("[Console]::OutputEncoding=[Text.Encoding]::UTF8;$ProgressPreference='SilentlyContinue';"
          "$ErrorActionPreference='Continue';")


def ps_cmd(script):
    return ["powershell", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", PS_PRE + script]


class LiveRunner:
    """Exécute des commandes et envoie leur sortie ligne par ligne (avec progression \\r) vers un callback."""

    def __init__(self, emit):
        self._emit = emit           # emit(list[{"t","k"}])
        self.proc = None
        self.cancelled = False
        self.out = []
        self._pend = []
        self._lock = threading.Lock()
        self._in_prog = False
        self._stop = None

    def start_flusher(self):
        self._stop = threading.Event()

        def loop():
            while not self._stop.wait(0.2):
                self.flush()
        threading.Thread(target=loop, daemon=True).start()

    def stop_flusher(self):
        if self._stop:
            self._stop.set()
        self.flush()

    def flush(self):
        with self._lock:
            lines, self._pend = self._pend, []
        if lines:
            self._emit(lines)

    def line(self, text, kind="out"):
        with self._lock:
            if kind == "prog" and self.out and self.out[-1][1] == "prog":
                self.out[-1] = (text, kind)
            else:
                self.out.append((text, kind))
            if kind == "prog" and self._pend and self._pend[-1]["k"] == "prog":
                self._pend[-1] = {"t": text, "k": kind}
            else:
                self._pend.append({"t": text, "k": kind})

    def cancel(self):
        self.cancelled = True
        p = self.proc
        if p and p.poll() is None:
            if IS_WIN:
                subprocess.run(["taskkill", "/PID", str(p.pid), "/T", "/F"], stdin=subprocess.DEVNULL,
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, creationflags=NO_WINDOW)
            else:
                p.kill()

    def _feed(self, text):
        lines = text.replace("\x00", "").split("\n")
        part = lines.pop()
        for ln in lines:
            segs = [s for s in ln.split("\r") if s.strip()]
            if segs:
                self.line(segs[-1].rstrip(), "prog" if (len(segs) > 1 or self._in_prog) else "out")
            self._in_prog = False
        if "\r" in part:
            segs = part.split("\r")
            part = segs[-1]
            done = [s for s in segs[:-1] if s.strip()]
            if done:
                self.line(done[-1].rstrip(), "prog")
                self._in_prog = True
        return part

    def stream(self, cmd, filt=None):
        """Lance cmd ; renvoie le code retour. filt(line)->(texte, kind) ou None pour ignorer."""
        p = subprocess.Popen(cmd, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                             creationflags=NO_WINDOW)
        self.proc = p
        self._in_prog = False
        buf, mode, part = b"", None, ""
        while True:
            chunk = p.stdout.read1(4096)
            if not chunk:
                break
            buf += chunk
            if mode is None:
                if len(buf) < 2:
                    continue
                mode = "u16" if buf[1:2] == b"\x00" or buf.count(b"\x00") * 3 > len(buf) else "b"
            if mode == "u16":
                n = len(buf) // 2 * 2
                text, buf = buf[:n].decode("utf-16-le", "replace"), buf[n:]
            else:
                i = max(buf.rfind(b"\n"), buf.rfind(b"\r"))
                if i < 0:
                    continue
                text, buf = decode_out(buf[:i + 1]), buf[i + 1:]
            part = self._feed(part + text)
        if buf:
            part = self._feed(part + (buf.decode("utf-16-le", "replace") if mode == "u16" else decode_out(buf)))
        if part.strip():
            self.line(part.strip(), "out")
        p.wait()
        self.proc = None
        return p.returncode


def is_admin():
    try:
        if IS_WIN:
            import ctypes
            return bool(ctypes.windll.shell32.IsUserAnAdmin())
        return os.geteuid() == 0
    except Exception:
        return False


def finish(code):
    try:
        sys.stdout.flush()
    except Exception:
        pass
    os._exit(code or 0)


# --------------------------------------------------------------------------- #
# Banc de test (mode --fulltest) : résultats JSONL + captures d'écran
# --------------------------------------------------------------------------- #
class TestKit:
    def __init__(self, outdir, app, bridge):
        import traceback  # noqa: F401
        self.dir = outdir
        os.makedirs(os.path.join(outdir, "screens"), exist_ok=True)
        self.app, self.b = app, bridge
        self.path = os.path.join(outdir, f"{app}.jsonl")
        self.t0 = time.time()
        self.counts = {"PASS": 0, "FAIL": 0, "WARN": 0, "INFO": 0}

    def rec(self, area, name, status, detail=""):
        status = {True: "PASS", False: "FAIL"}.get(status, status)
        self.counts[status] = self.counts.get(status, 0) + 1
        line = {"app": self.app, "area": area, "test": name, "status": status, "detail": str(detail)[:3000],
                "t": round(time.time() - self.t0, 1)}
        with open(self.path, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(line, ensure_ascii=False) + "\n")
        return status == "PASS"

    def check(self, area, name, cond, detail=""):
        return self.rec(area, name, "PASS" if cond else "FAIL", detail)

    def guard(self, area, name, fn):
        """Exécute fn() ; une exception devient un FAIL avec la trace."""
        import traceback
        try:
            return fn()
        except Exception:
            self.rec(area, name, "FAIL", "Exception : " + traceback.format_exc()[-1500:])
            return None

    def js(self, code):
        return self.b._eval(code)

    def js_errors(self, area):
        errs = self.js("JSON.stringify(window.__errs||[])")
        try:
            errs = json.loads(errs or "[]")
        except Exception:
            errs = [str(errs)]
        self.check(area, "Aucune erreur JavaScript", not errs, "; ".join(errs[:10]) or "aucune")
        self.js("window.__errs=[]")

    @staticmethod
    def wait(cond, timeout=60, step=0.5):
        t = time.time()
        while time.time() - t < timeout:
            try:
                if cond():
                    return True
            except Exception:
                pass
            time.sleep(step)
        return False

    def shot(self, name):
        if not IS_WIN:
            return
        f = os.path.join(self.dir, "screens", f"{self.app}_{name}.png")
        script = ("Add-Type -MemberDefinition '[DllImport(\"user32.dll\")] public static extern bool SetProcessDPIAware();' -Name U -Namespace W;"
                  "[W.U]::SetProcessDPIAware()|Out-Null;Add-Type -AssemblyName System.Windows.Forms,System.Drawing;"
                  "$b=[System.Windows.Forms.Screen]::PrimaryScreen.Bounds;$bmp=New-Object System.Drawing.Bitmap $b.Width,$b.Height;"
                  "$g=[System.Drawing.Graphics]::FromImage($bmp);$g.CopyFromScreen($b.Location,[System.Drawing.Point]::Empty,$b.Size);"
                  f"$bmp.Save('{f}',[System.Drawing.Imaging.ImageFormat]::Png)")
        time.sleep(0.8)
        run(ps_cmd(script), timeout=30)

    def finish(self):
        self.rec("Bilan", "Fin des tests", "INFO", json.dumps(self.counts) + f" en {time.time() - self.t0:.0f} s")
        try:
            self.b._window.destroy()
        except Exception:
            pass
